def parse_tool_call(text: str) -> tuple[str | None, dict | None]:
    m = FUNC_RE.search(text or "")
    if not m:
        return None, None
    tool = m.group(1)
    args: dict = {}
    for k, v in PARAM_RE.findall(text):
        v = v.strip()
        if k in INT_ARGS:
            try:
                args[k] = int(v)
            except ValueError:
                args[k] = v
        else:
            args[k] = v
    return tool, args
